function idesMoneyPanel(){
 var h='<p>Review your issued DoD findings with counsel. Ask how credited service and the stability finding affect your case. A VA rating does not determine your military disposition.</p><details class="c1-disclosure"><summary>General disposition rules</summary><p>These branches assume an unfit, compensable disability and all applicable service, line-of-duty, misconduct and pre-service requirements are met. Your service makes the individual decision.</p><table class="ides-table"><thead><tr><th>DoD findings and credit</th><th>General branch</th></tr></thead><tbody><tr><td>Below 30%; under 20 disability-credited years</td><td>Disability severance, subject to the stated eligibility conditions. Severance alone provides no retiree TRICARE or SBP.</td></tr><tr><td>30% or more; under 20 credited years; permanent and stable</td><td>Permanent Disability Retired List (PDRL).</td></tr><tr><td>At least 20 disability-credited years; permanent and stable</td><td>PDRL may apply below 30% if other requirements are met.</td></tr><tr><td>Otherwise retirement-qualified; potentially permanent but not stable</td><td>Temporary Disability Retired List (TDRL), with a 50% pay-base floor before offsets and required follow-up exams.</td></tr><tr><td>Fit or noncompensable</td><td>Ask counsel about the separate disposition. Do not apply this pay table.</td></tr></tbody></table><p>Disability credit under 10 USC 1208 differs from Reserve qualifying years. Ask Reserve personnel to verify the record before any severance or deferred-retirement choice.</p></details>'+idesButton('ides-estimate','Compare gross formulas')+'<details class="c1-disclosure"><summary>Synthetic gross examples</summary><p>Estimate. DoD and DFAS decide. These examples assume the stated branch applies; amounts are before deductions.</p><table class="ides-table"><thead><tr><th>Inputs</th><th>Gross illustration</th></tr></thead><tbody><tr><td>10 years, 40% DoD, $5,000 retired-pay base</td><td>$2,000 disability method; $1,250 legacy or $1,000 BRS longevity. TDRL minimum: $2,500.</td></tr><tr><td>20 years, 30% DoD, $6,000 base</td><td>Longevity is larger: $3,000 legacy or $2,400 BRS; disability method: $1,800.</td></tr><tr><td>10 years, 100% DoD, $5,000 base</td><td>Disability method caps at $3,750.</td></tr><tr><td>$4,000 basic pay; 4 years, 8 months</td><td>Five rounded severance years: $40,000. Qualifying six-year combat minimum: $48,000.</td></tr></tbody></table></details><details class="c1-disclosure"><summary>From gross entitlement to deposits</summary><p>Ordinarily VA compensation offsets retired pay dollar for dollar, up to retired pay. Take your VA and retired-pay notices to DFAS and accredited help to confirm the waiver and any relief. Zero DFAS cash does not itself end retirement status.</p><p>CRDP requires qualifying retirement and a VA rating of at least 50%, with Chapter 61 service limits. DFAS ordinarily establishes CRDP without a separate application; ask it to confirm your account. High VA ratings alone do not qualify an under-20 Chapter 61 retiree.</p><p>CRSC uses a separate Navy application and may cover qualifying under-20 Chapter 61 retirees, subject to payment limits. CRSC and CRDP cannot pay for the same month. Ask the Navy CRSC Board about Soto and its current correction route; no six-year cutoff is calculated here.</p><p>Tax-free severance can still be subject to VA recoupment. Ask separately about combat findings, taxes, SBP premiums, VA waiver and recovery. Compare your actual payment and withholding notices with qualified help.</p></details><h3>Check each part separately</h3>';
 ['ides-retired-pay-check','ides-severance','ides-concurrent-pay','ides-crsc','ides-recoupment','ides-tax-review','ret-sbp','ides-reserve-counsel'].forEach(function(id){if(S.items[id])h+=idesButton('item-drawer',S.items[id].label||S.items[id].title,id);});
 h+=idesConflicts(['IDS-C14','IDS-C17','IDS-C20','IDS-C21','IDS-C22','IDS-C23'])+idesHelp();idesDialog('Money and benefits',h);
}
function idesEstimator(){
 var h='<p>Estimate. DoD and DFAS decide.</p><p>Enter each input from your records, or choose your own comparison assumptions. This compares gross formulas only. It does not establish eligibility or suggest a rating.</p><div class="ides-form">';
 [['basicPay','Monthly basic pay for severance'],['retiredBase','Monthly retired-pay base (usually high-36 basic pay)'],['years','Full credited years'],['months','Additional full months (0 to 11)'],['rating','DoD rating to compare, percent']].forEach(function(x){h+='<label class="field"><span>'+x[1]+'</span><input id="idesMoney-'+x[0]+'" type="number" min="0" step="'+(['years','months'].includes(x[0])?'1':'any')+'"></label>';});
 [['system','Retirement system',[['legacy','Legacy: 2.5% per year'],['brs','BRS: 2% per year']]],['status','Retired-pay comparison',[['pdrl','PDRL'],['tdrl','TDRL: 50% minimum']]],['minimum','Severance minimum assumption',[['standard','Standard: three years'],['combat','Qualifying combat: six years']]]].forEach(function(x){h+='<label class="field"><span>'+x[1]+'</span><select id="idesMoney-'+x[0]+'"><option value="">Choose</option>'+x[2].map(function(v){return'<option value="'+v[0]+'">'+v[1]+'</option>';}).join('')+'</select></label>';});
 h+='<p>Ask personnel to verify disability-credited years separately from Reserve qualifying years or calendar membership. The retired-pay base excludes BAH and BAS. Full additional months count as twelfths; remaining days do not.</p><p>Ask the pay office about final-pay, short-service, higher-grade, promotion and Reserve pay-base rules. A Reserve drill check is not the retired-pay base.</p>'+idesButton('ides-estimate-run','Compare inputs')+'<p id="idesMoneyError" role="alert"></p><div id="idesMoneyResult" aria-live="polite"></div></div>'+idesSourceHtml(IDES.byId['IDS-R037'])+idesSourceHtml(IDES.byId['IDS-R038'])+idesHelp();idesDialog('Compare gross formulas',h);
}
function idesEstimateRun(){
 var input={};['basicPay','retiredBase','years','months','rating','system','status','minimum'].forEach(function(k){input[k]=el('idesMoney-'+k).value;});
 try{var r=window.MusterOutIDES.grossEstimate(input),pdrl=window.MusterOutIDES.grossEstimate(Object.assign({},input,{status:'pdrl'})),tdrl=window.MusterOutIDES.grossEstimate(Object.assign({},input,{status:'tdrl'})),money=idesMoney,base=money(Number(input.retiredBase)),basic=money(Number(input.basicPay));el('idesMoneyError').textContent='';el('idesMoneyResult').innerHTML='<h3>Estimate. DoD and DFAS decide.</h3><p>If disability retirement applies:</p><table class="ides-table"><thead><tr><th>Gross monthly method</th><th>Calculation</th></tr></thead><tbody><tr><td>Disability method</td><td>'+esc(base)+' x min('+esc(input.rating)+'%, 75%) = '+money(r.disability)+'</td></tr><tr><td>Longevity method</td><td>'+esc(base)+' x ('+esc(input.years)+' + '+esc(input.months)+'/12) x '+esc(r.rate*100)+'% = '+money(r.longevity)+'</td></tr>'+(input.status==='tdrl'?'<tr><td>TDRL minimum</td><td>'+esc(base)+' x 50% = '+money(r.tdrlFloor)+'</td></tr>':'')+'</tbody></table><p><strong>If your retirement is permanent (PDRL): '+money(pdrl.retiredGross)+' gross per month, '+(pdrl.method==='Equal methods'?'the two methods are equal.':'the larger of the two methods ('+esc(pdrl.method.toLowerCase())+').')+'</strong></p><p><strong>If you are placed on TDRL: at least '+money(tdrl.retiredGross)+' gross per month while on TDRL.</strong></p><p>The disability-method cap is 75%. Ask the pay office about the separate longevity computation.</p><p>If disability severance applies:</p><p>2 x '+esc(basic)+' x '+r.severanceYears+' credited years = <strong>'+money(r.severanceGross)+' gross lump sum.</strong> Additional service of at least six months rounds up; apply the selected three- or six-year minimum and 19-year maximum. The rating does not multiply severance.</p><p>These are alternative statutory branches. Ask counsel and the pay office which applies. Taxes, VA waiver, CRDP, CRSC, SBP premiums and recoupment require separate review; these are not deposit estimates.</p>';el('idesMoneyResult').scrollIntoView({block:'start'});}
 catch(err){el('idesMoneyError').textContent=err.message;el('idesMoneyResult').textContent='';}
}
function idesTransition(){
 var h='<p>Confirm medical dates and extensions with MMSR-4 and IPAC. Your orders, authorized service end, actual release and leave departure are separate events.</p><h3>EAS and leave</h3><p>Ask about the actual disability-order date. Ordinary first-of-month retirement and FMCR assumptions do not set it. Accepting findings does not promise a fixed time to depart.</p><p>Review your LES, leave balance, duty restrictions and proposed absence with IPAC. Leave approval does not establish actual release. You can keep leave records while the end date is unknown.</p>'+idesButton('ides-leave','Leave records')+'<h3>Transition Readiness Program</h3><p>Start with TRP now, even without an EAS. For an ordinary confirmed planning date, initial and pre-separation counseling are due 365 days before EAS, workshops 180, Capstone 120 and command verification 90. Ask TRP for an immediate schedule in a short-notice medical case.</p><p>Confirm appointments separately from completion. Complete required TRP work before SkillBridge participation.</p>';
 ['ides-extension','sep-eas','sep-orders','va-service-end','sep-ic','sep-presep','sep-trs','sep-capstone','sep-cv'].forEach(function(id){if(S.items[id])h+=idesButton('item-drawer',S.items[id].label||S.items[id].title,id);});
 h+='<h3>SkillBridge inquiry and approval</h3><p>Ask the installation coordinator and command which current authority applies. An uncertain EAS does not establish eligibility, duration or approval.</p>'+idesConflicts(['IDS-C16'])+idesSourceHtml(IDES.byId['IDS-R028']);['sb-coord','sb-packet','sb-approval','sb-sequence','sb-run','sb-start'].forEach(function(id){if(S.items[id])h+=idesButton('item-drawer',S.items[id].label||S.items[id].title,id);});h+='<p>Keep care, exams and duty requirements in the plan. Ask the VRC or WWR about suitable-work planning while your date is unresolved.</p>'+idesHelp();idesDialog('EAS, leave and programs',h);
}
function idesUndatedLeave(){var L=S.ledger,h='<div class="des-leave-summary"><div><h2>Leave balance</h2><p>'+(L.balance==null?'Use your latest Leave and Earnings Statement.':esc(L.balance)+' days'+(L.asOf?' · '+esc(mil(parseD(L.asOf))):''))+'</p></div>'+(canEdit()?idesButton('ledger-edit',L.balance==null?'Add balance':'Edit balance'):'')+'</div><p>Confirm your authorized service end with MMSR-4 or IPAC before using a leave forecast. You can keep proposed leave records while the date is unknown.</p>'+leaveSlaReview()+'<section class="des-leave-blocks"><div class="phead"><h3>Leave blocks</h3>'+(canEdit()?idesButton('blk-new','Add leave'):'')+'</div>'+(S.blocks.length?S.blocks.slice().sort(function(a,b){return(a.start||'').localeCompare(b.start||'');}).map(blockRow).join(''):'<p>No leave blocks saved.</p>')+'</section><p>Ask your command and IPAC to confirm leave approval. Leave departure does not establish actual release.</p>';return h;}
function idesLeave(){openLeavePlanner('Leave records');UI.c1Dialog.overlay.classList.add('ides-dialog');el('c1DialogTitle').dataset.idesProgrammatic='true';var body=UI.c1Dialog?.overlay.querySelector('.c1-dialog-body');if(body)body.insertAdjacentHTML('afterbegin','<p>Confirm medical dates, leave approval and your actual release separately with MMSR-4 and IPAC. Keep a fallback if orders change.</p>'+idesHelp());}
function idesLessons(){var h='<p>Use these prompts with your office. Personal stories cannot establish a legal rule or forecast when your case will finish.</p>';IDES_DATA.lessons.forEach(function(l){h+='<details class="c1-disclosure"><summary>'+esc(l.title)+'</summary><p><strong>'+esc(l.confidence)+'</strong></p><p>'+esc(l.text)+'</p><details><summary>Evidence and limits</summary>'+l.sources.map(function(id){var source=IDES_DATA.sources[id];return'<p>'+idesLink(source.url,idesText(source.title))+'<small>Checked '+esc(mil(parseD(source.verified)))+'</small></p>';}).join('')+'</details></details>';});h+=idesHelp();idesDialog('Practical lessons',h);}
function idesDraftText(record){var rows=['Unsaved IDES changes','Case: '+(record.caseLabel||'Current case'),'Review: '+(record.cycleLabel||'Current review'),'Stage: '+idesLabel(IDES_DATA.stages,record.stage),'Disposition: '+idesLabel(IDES_DATA.outcomes,record.outcome)];Object.entries(record.branchConfirmations||{}).forEach(function(pair){rows.push((IDES.byId[pair[0]]?.title||'Office decision')+': '+idesBranchLabel(pair[1].branch));});Object.entries(record.calendarConfirmations||{}).forEach(function(pair){rows.push(idesCalendarLabel(pair[0])+': '+(pair[1].version||'Version not recorded'));rows.push('Covered years: '+IDES.values(pair[1].years).join(', '));rows.push('Nonworking days: '+(IDES.values(pair[1].holidays).map(function(day){return mil(parseD(day));}).join(', ')||'None entered'));});Object.entries(record.events||{}).forEach(function(pair){Object.values(pair[1]).forEach(function(e){rows.push((IDES_DATA.events[pair[0]]?.label||'Saved event')+': '+mil(parseD(e.date))+'; '+idesBasisLabel(e.confirmationBasis));});});return rows.join('\n');}
function idesDraftSummary(record){return idesDraftText(record).split('\n').map(function(line){return'<p>'+esc(line)+'</p>';}).join('');}

