   if(a==='ides-branch-save'){if(!el('idesBranchConfirmed').checked)throw Error('Your PEBLO or counsel must confirm which branch applies before you save it.');var branch=el('idesBranch').value;await idesChange(function(s){s.branchConfirmations[id]={branch:branch,caseId:s.caseId,cycleId:s.cycleId,confirmedByMarine:true,officeConfirmed:true,confirmedAt:nowIso(),confirmationBasis:'office_confirmation'};return s;});c1Close(true);}
   if(a==='ides-calendar-save'){var years=el('idesCalendarYears').value.split(',').map(function(x){return Number(x.trim());}),holidays=el('idesCalendarHolidays').value.split(/\n/).filter(function(x){return x.trim();}).map(idesDateInput),version=el('idesCalendarVersion').value,url=el('idesCalendarSource').value;if(!version||!years.length||years.some(function(n){return!Number.isInteger(n)||n<1900||n>2200;})||holidays.some(function(x){return IDES.parse(x)==null;})||!safeUrl(url)||!el('idesCalendarWeekdays').checked||!el('idesCalendarConfirmed').checked)throw Error('Check the calendar version and covered years, then confirm its URL and nonworking days with the office.');var cid=UI.idesCalendar;await idesChange(function(s){function flags(values,prior){var map={};Object.keys(prior||{}).forEach(function(k){map[k]=false;});values.forEach(function(k){map[k]=true;});return map;}var prior=s.calendarConfirmations[cid];s.calendarConfirmations[cid]={id:cid,version:version,years:flags(years,prior?.years),sourceUrl:url,workdays:flags([1,2,3,4,5],prior?.workdays),holidays:flags(holidays,prior?.holidays),exceptions:{},confirmedByMarine:true,officeConfirmed:true,confirmedAt:nowIso()};return s;});c1Close(true);}
