function idesRecoverNotice(){if(!idesActive()||C1_DEMO||IDES_SAVING)return;try{var d=idesDraftPacket();if(!d?.record)return;if(canonicalSeed(d.record)===canonicalSeed(S.ides)){idesDropDraft();UI.idesSaveError='';IDES_FAILED_TYPES.clear();IDES_FAILED_REQUIREMENTS.clear();return;}idesMarkFailed(S.ides,d.record);UI.idesSaveError='Unsaved IDES changes are kept on this device. Review them before saving another change.';}catch(_){UI.idesSaveError='The IDES draft could not be read. Keep this device open and get help.';}}

